import copy
from datetime import datetime, timedelta, timezone
from pathlib import Path
import unittest
from unittest.mock import patch

from streamlit.testing.v1 import AppTest

import activity_sources
import api_client
import calendar_export
import calendar_import
import config
import database
import importers
import ui_components
import uniclubs_database
import uniclubs_export


NOW = datetime(2026, 11, 2, 10)
SOURCE_CLOCK = datetime(2026, 11, 2, 9, tzinfo=timezone.utc)
ROOT = Path(__file__).resolve().parents[1]
APP_TIMEOUT = 180
SOURCE_ID = 'uniclubs:fixture-event'
CLOSED_ID = 'uniclubs:fixture-design'
SOURCE_TITLE = 'UniClubs Fixture Tech Workshop'
UPDATED_TITLE = 'UniClubs Fixture Tech Workshop Updated'


def values(elements):
    """Return actual element text without depending on Streamlit's Markdown wrappers."""
    return [element.value for element in elements]


def source_records(updated=False):
    """Return two public fixtures, one bookable event and one with closed registration."""
    club = {'external_id': 'fixture-club', 'name': 'Fixture Tech Club',
            'source_url': 'https://uniclubs.ch/hsg/clubs/fixture-tech-club'}
    event = {
        'external_id': 'fixture-event', 'club_external_id': 'fixture-club',
        'title': UPDATED_TITLE if updated else SOURCE_TITLE,
        'start_utc': '2026-11-03T20:00:00Z' if updated else '2026-11-03T19:00:00Z',
        'end_utc': '2026-11-03T21:00:00Z' if updated else '2026-11-03T20:00:00Z',
        'location': 'SQUARE', 'event_type': 'workshop', 'publication_status': 'published',
        'availability_state': 'open', 'requires_membership': False,
        'source_url': 'https://uniclubs.ch/hsg/clubs/fixture-tech-club/events/fixture-event',
    }
    closed = event.copy()
    closed.update(external_id='fixture-design', title='UniClubs Fixture Design Talk',
                  start_utc='2026-11-04T19:00:00Z', end_utc='2026-11-04T20:00:00Z',
                  availability_state='sales_closed',
                  source_url='https://uniclubs.ch/hsg/clubs/fixture-tech-club/events/'
                             'fixture-design')
    return [club], [event, closed]


class UniClubsScenario(unittest.TestCase):
    """Follow a real public event from feed to private calendar plan without legacy copies."""

    def setUp(self):
        """Isolate clocks, replace the remote feed and capture the actual ICS exports."""
        if config.DATA_DIR == ROOT / 'data':
            raise RuntimeError('Run python -m views.check_uniclubs with isolated paths.')
        self.connection = None
        self.exports = {}
        self.download_error = False
        self.clock = NOW
        self.fixture_catalog = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.fixture_catalog.close)
        uniclubs_database.init_db(self.fixture_catalog)
        self.update_document(False)
        self.build_ics = calendar_export.build_ics
        self.start_patch(config, 'local_now', side_effect=lambda now=None: now or self.clock)
        self.start_patch(importers, 'fetch_public_uniclubs_feed', side_effect=self.fetch_document)
        self.start_patch(api_client, 'is_api_available', return_value=False)
        self.start_patch(api_client.requests, 'get', side_effect=AssertionError('External HTTP'))
        self.start_patch(importers, 'fetch_json', side_effect=AssertionError('External import'))
        self.start_patch(calendar_import, 'fetch_ics_text',
                         side_effect=AssertionError('External calendar'))
        self.start_patch(calendar_export, 'build_ics', side_effect=self.capture_export)
        self.addCleanup(self.close_resources)

    def start_patch(self, module, name, **arguments):
        """Register patch cleanup even when setup or a Streamlit assertion fails."""
        replacement = patch.object(module, name, **arguments)
        self.addCleanup(replacement.stop)
        return replacement.start()

    def update_document(self, updated):
        """Advance a synthetic publisher snapshot while preserving fixture source identities."""
        clubs, events = source_records(updated)
        clock = SOURCE_CLOCK + timedelta(minutes=5) if updated else SOURCE_CLOCK
        uniclubs_database.sync_catalog(self.fixture_catalog, clubs, events, now=clock)
        self.document = uniclubs_export.build_export(self.fixture_catalog)
        uniclubs_export.write_export(self.fixture_catalog, config.UNICLUBS_EXPORT_FILE)

    def fetch_document(self):
        """Supply a complete public document or a controlled network failure."""
        if self.download_error:
            raise ValueError('Fixture feed is temporarily unavailable.')
        return copy.deepcopy(self.document)

    def capture_export(self, event, *arguments, **keywords):
        """Capture the real ICS output without replacing its implementation."""
        text = self.build_ics(event, *arguments, **keywords)
        self.exports[event.event_id, bool(keywords.get('cancel', False))] = text
        return text

    def close_resources(self):
        """Close only this scenario's resources before its temporary directory is removed."""
        if self.connection is not None:
            self.connection.close()
        if config.DB_FILE.exists():
            ui_components.cached_connection().close()
        ui_components.clear_data_caches()
        ui_components.cached_connection.clear()
        ui_components.cached_uniclubs_refresh.clear()

    def clean(self):
        """Reject both uncaught exceptions and errors caught by the app's UI handlers."""
        self.assertFalse(self.app.exception, values(self.app.exception))
        self.assertFalse(self.app.error, values(self.app.error))

    def new_session(self):
        """Load the real app shell against the same isolated persistent databases."""
        self.app = AppTest.from_file(str(ROOT / 'app.py'), default_timeout=APP_TIMEOUT).run()
        self.clean()

    def details(self, event_id=SOURCE_ID):
        """Requeue a source-specific dialog for AppTest's full-script rerun behavior."""
        self.app.session_state['ww_open_event_id'] = event_id
        self.app.run()
        self.clean()

    def test_public_feed_calendar_roundtrip(self):
        """Verify public data, private planning, rescheduling, fallback and cancellation."""
        self.onboard()
        self.check_public_display()
        self.favorite_and_confirm()
        self.restore_and_update()
        self.fail_feed_and_cancel()
        self.answer_source_feedback()
        self.organizer_cancellation()

    def onboard(self):
        """Create a local profile without unrelated demo feedback prompts."""
        self.new_session()
        self.app.button(key='ww_welcome_next').click().run()
        self.app.text_input(key='ww_onboarding_name').set_value('Alex')
        self.app.checkbox(key='ww_onboarding_career').check()
        self.app.checkbox(key='ww_demo_history').uncheck()
        self.app.button(key='ww_focus_next').click().run()
        self.app.button(key='ww_finish_onboarding').click().run()
        self.clean()
        self.connection = database.get_connection(config.DB_FILE)
        self.user_id = database.get_current_user_id(self.connection)

    def check_public_display(self):
        """Expose source events separately and retain their original source-status meaning."""
        texts = values(self.app.text) + values(self.app.markdown) + values(self.app.caption)
        self.assertTrue(any(SOURCE_TITLE in text for text in texts), texts)
        self.assertTrue(any('UniClubs' in text for text in values(self.app.sidebar.caption)))
        self.assertTrue(any('UniClubs this week' in item.label for item in self.app.expander))
        self.app.button(key='ww_uniclubs_catalog_details_' + CLOSED_ID).click().run()
        self.clean()
        self.assertFalse(any(button.key == 'ww_confirm_event' for button in self.app.button))
        self.assertTrue(any('closed' in text.lower() for text in
                            values(self.app.info) + values(self.app.caption)))
        self.details()
        self.assertTrue(any(button.key == 'ww_confirm_event' for button in self.app.button))
        count = self.connection.execute('''SELECT count(*) FROM series
            WHERE external_id IN (?, ?)''', ('fixture-event', 'fixture-design')).fetchone()[0]
        self.assertEqual(count, 0)

    def favorite_and_confirm(self):
        """Save new-source favorites and a plan, then round-trip the generated ICS marker."""
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.checkbox(key='ww_favorite_series_' + SOURCE_ID).check().run()
        self.clean()
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.checkbox(key='ww_favorite_club_' + SOURCE_ID).check().run()
        self.clean()
        profile = activity_sources.get_profile(self.connection, self.user_id)
        self.assertIn('uniclubs-series:fixture-event', profile.favorite_series_ids)
        self.assertIn('uniclubs-club:fixture-club', profile.favorite_club_ids)
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        interaction = activity_sources.get_interaction(self.connection, self.user_id, SOURCE_ID)
        self.assertEqual(interaction['status'], 'confirmed')
        legacy_count = self.connection.execute('''SELECT count(*) FROM interactions
            WHERE event_id=?''', (SOURCE_ID,)).fetchone()[0]
        self.assertEqual(legacy_count, 0)
        self.original_uid = calendar_export.make_uid(activity_sources.load_event(SOURCE_ID))
        self.assertIn('UID:' + self.original_uid, self.exports[SOURCE_ID, False])
        blocks, _, recognized = calendar_import.parse_calendar(
            self.exports[SOURCE_ID, False], datetime(2026, 11, 3), datetime(2026, 11, 4))
        self.assertIn(SOURCE_ID, recognized)
        self.assertEqual(blocks[0].start, datetime(2026, 11, 3, 20))
        self.assertEqual(blocks[0].end, datetime(2026, 11, 3, 21))
        self.assertTrue(any(button.key and button.key.startswith('ww_timeline_event_')
                            and button.key.endswith(SOURCE_ID) for button in self.app.button))

    def restore_and_update(self):
        """Keep private planning across sessions and move the same source event after refresh."""
        original = activity_sources.load_event(SOURCE_ID)
        self.new_session()
        interaction = activity_sources.get_interaction(self.connection, self.user_id, SOURCE_ID)
        self.assertEqual(interaction['status'], 'confirmed')
        profile = activity_sources.get_profile(self.connection, self.user_id)
        self.assertIn('uniclubs-series:fixture-event', profile.favorite_series_ids)
        self.assertIn('uniclubs-club:fixture-club', profile.favorite_club_ids)
        self.update_document(True)
        ui_components.cached_uniclubs_refresh.clear()
        self.app.run()
        self.clean()
        changed = activity_sources.load_event(SOURCE_ID)
        self.assertEqual(changed.event_id, original.event_id)
        self.assertEqual(changed.start, datetime(2026, 11, 3, 21))
        self.assertEqual(changed.title, UPDATED_TITLE)
        self.assertEqual(calendar_export.make_uid(changed), self.original_uid)
        self.details()
        self.assertTrue(any(UPDATED_TITLE in value for value in values(self.app.subheader)))

    def fail_feed_and_cancel(self):
        """Retain the updated plan during an outage and export a cancellation with the same UID."""
        self.download_error = True
        ui_components.cached_uniclubs_refresh.clear()
        self.app.run()
        self.clean()
        changed = activity_sources.load_event(SOURCE_ID)
        self.assertEqual(changed.title, UPDATED_TITLE)
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID)['status'], 'confirmed')
        status = ui_components.uniclubs_status()
        self.assertFalse(status['ok'])
        self.assertTrue(status['catalog_available'])
        fallback = values(self.app.warning) + values(self.app.caption)
        self.assertIn(status['message'], fallback)
        self.details()
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.button(key='ww_cancel_event').click().run()
        self.clean()
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, SOURCE_ID)['status'], 'cancelled')
        text = self.exports[SOURCE_ID, True]
        self.assertIn('UID:' + self.original_uid, text)
        self.assertIn('METHOD:CANCEL', text)
        self.assertFalse(any(button.key and button.key.startswith('ww_timeline_event_')
                             and button.key.endswith(SOURCE_ID) for button in self.app.button))

    def answer_source_feedback(self):
        """Route ended source feedback privately and expose it to the production-model inputs."""
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        revision = activity_sources.get_rating_revision(self.connection)
        self.clock = datetime(2026, 11, 4, 10)
        self.new_session()
        key = 'ww_popup_feedback_' + SOURCE_ID
        self.app.button(key=key + '_yes').click().run()
        self.clean()
        self.app.feedback(key=key + '_stars').set_value(4).run()
        self.clean()
        interaction = activity_sources.get_interaction(self.connection, self.user_id, SOURCE_ID)
        self.assertEqual(interaction['status'], 'attended')
        self.assertEqual(interaction['rating'], 5)
        self.assertGreater(activity_sources.get_rating_revision(self.connection), revision)
        examples = activity_sources.training_examples(self.connection, self.clock)
        self.assertEqual(len(examples), 1)
        self.assertEqual(examples[0]['event'].event_id, SOURCE_ID)
        self.assertEqual(examples[0]['rating'], 5)

    def organizer_cancellation(self):
        """Do not offer a regular export or feedback after an explicit source cancellation."""
        if any(button.key == 'ww_feedback_done' for button in self.app.button):
            self.app.button(key='ww_feedback_done').click().run()
        clubs, events = source_records(True)
        events[0]['publication_status'] = 'cancelled'
        uniclubs_database.sync_catalog(self.fixture_catalog, clubs, events,
                                       now=SOURCE_CLOCK + timedelta(days=2))
        self.document = uniclubs_export.build_export(self.fixture_catalog)
        self.download_error = False
        self.exports.clear()
        ui_components.cached_uniclubs_refresh.clear()
        self.details()
        self.assertTrue(any('organizer cancelled' in value.lower()
                            for value in values(self.app.warning)))
        self.assertNotIn((SOURCE_ID, False), self.exports)
        self.assertIn((SOURCE_ID, True), self.exports)
        self.assertIn('UID:' + self.original_uid, self.exports[SOURCE_ID, True])
        self.assertEqual(activity_sources.training_examples(self.connection, self.clock), [])
